#include <stdio.h>

typedef struct Node {
    int score;
    struct Node *next;
} Node;

int main(void) {
    Node a = {90, NULL};
    Node b = {85, NULL};
    Node c = {95, NULL};
    a.next = &b;
    b.next = &c;

    int best = a.score;
    for (Node *p = a.next; p != NULL; p = p->next) {
        if (p->score > best) {
            best = p->score;
        }
    }
    printf("最高分：%d\n", best);
    return 0;
}
